"""
Interfaz web de tu cronograma (versión 3: materias + tarjeta de detalle).

Reutiliza paso1 a paso5 (deben estar en la misma carpeta).
Para correrla:  python app.py   y abrir  http://localhost:5000
"""

import json
import os
import threading
import time
from datetime import datetime, timedelta

from dotenv import load_dotenv
import base64

from flask import Flask, Response, redirect, render_template_string, request, url_for
from google import genai

from paso1_classroom import obtener_servicio
from paso2_pendientes import ESTADOS_PENDIENTES, ZONA, obtener_tareas
from paso4_analizar import abrir_bd, analizar_con_ia, clave_de
from avisos import procesar
from paso5_cronograma import DIAS_SEMANA, armar_cronograma, estado_de

# "0.0.0.0" = se puede abrir desde el celular (mismo Wi-Fi).
load_dotenv()
COMPARTIR = os.getenv("ACCESO_CELULAR", "no").strip().lower() in ("si", "sí", "1", "yes")
HOST = "0.0.0.0" if COMPARTIR else "127.0.0.1"
PUERTO = 5000
MINUTOS = 15  # cada cuánto revisa Classroom por sí sola

MESES = ["enero", "febrero", "marzo", "abril", "mayo", "junio", "julio",
         "agosto", "septiembre", "octubre", "noviembre", "diciembre"]
NIVELES = ["Sin análisis", "Muy fácil", "Fácil", "Media", "Difícil", "Muy difícil"]
COLORES = ["#ea580c", "#2563eb", "#7c3aed", "#db2777", "#16a34a", "#d97706"]

# Tu logo (el coco), guardado dentro del propio archivo para no depender de otro.
LOGO_COCO = ""

app = Flask(__name__)
estado = {"datos": None, "actualizado": None, "error": None}
candado = threading.Lock()


def bd_con_manuales():
    """Abre la base de datos y se asegura de que exista la tabla de tareas manuales."""
    bd = abrir_bd()
    bd.execute("""CREATE TABLE IF NOT EXISTS manuales (
        id INTEGER PRIMARY KEY AUTOINCREMENT, curso TEXT, titulo TEXT,
        descripcion TEXT, fecha TEXT, hecha INTEGER DEFAULT 0)""")
    # Lo que tú decides sobre tareas de Classroom: ponerles fecha a mano o ignorarlas.
    bd.execute("""CREATE TABLE IF NOT EXISTS ajustes (
        clave TEXT PRIMARY KEY, fecha TEXT, ignorada INTEGER DEFAULT 0)""")
    return bd


def juntar(bd, tareas):
    """Une cada tarea de Classroom con su análisis de la IA (horas, dificultad, pasos)."""
    items = []
    for t in tareas:
        fila = bd.execute("SELECT horas, dificultad, pasos FROM analisis WHERE clave = ?",
                          (clave_de(t),)).fetchone()
        item = dict(t)
        item.update(analizado=fila is not None, fin=None,
                    horas=(fila[0] or 1.0) if fila else 1.0,
                    dificultad=int(fila[1] or 0) if fila else 0,
                    pasos=json.loads(fila[2]) if fila else [])
        items.append(item)
    return items


def faltan(limite, hoy):
    """Texto corto de cuánto falta para la entrega."""
    if not limite:
        return ""
    n = (limite.date() - hoy).days
    return "Entrega hoy" if n == 0 else "Entrega mañana" if n == 1 else f"Faltan {n} días"


def preparar(items, dias, cursos, hoy):
    """Convierte todo en datos simples para la página."""
    tareas = {}
    for n, item in enumerate(items):
        item["id"] = f"t{n}"
        d = min(max(item["dificultad"], 0), 5)
        item["puntos"] = "●" * d + "○" * (5 - d)
        tareas[item["id"]] = {
            "curso": item["curso"], "titulo": item["titulo"],
            "descripcion": item["descripcion"], "pasos": item["pasos"],
            "link": item["link"], "manual": item.get("manual_id"), "clave": clave_de(item),
            "sinfecha": item["limite"] is None and not item.get("manual_id"), "puntos": item["puntos"] if item["analizado"] else "",
            "nivel": NIVELES[d], "n": d if item["analizado"] else 0,
            "color": COLORES[sum(map(ord, item["curso"])) % len(COLORES)],
            "faltan": faltan(item["limite"], hoy), "horas": f"{item['horas']:g}" if item["analizado"] else "?",
            "entrega": ("Entrega: " + item["limite"].strftime("%d/%m %H:%M")) if item["limite"]
                       else "Sin fecha de entrega",
        }

    vistos, por_dia = set(), []
    for dia in sorted(dias):
        bloques = []
        for item, horas in dias[dia]:
            bloques.append({"id": item["id"], "curso": item["curso"], "titulo": item["titulo"],
                            "horas": f"{horas:g}", "puntos": item["puntos"],
                            "paso": item["pasos"][0] if item["pasos"] and item["id"] not in vistos else None})
            vistos.add(item["id"])
        por_dia.append({"fecha": dia, "bloques": bloques,
                        "total": f"{sum(h for _, h in dias[dia]):g}"})

    cal = {}
    for item in items:
        if item["limite"]:
            cal.setdefault(item["limite"].date().isoformat(), {"e": [], "p": []})["e"].append(item["id"])
    for dia in dias:
        for item, _ in dias[dia]:
            plan = cal.setdefault(dia.isoformat(), {"e": [], "p": []})["p"]
            if item["id"] not in plan:
                plan.append(item["id"])

    materias = []
    for c in cursos:
        nombre = c["name"]
        suyas = sorted((i for i in items if i["curso"] == nombre),
                       key=lambda i: i["limite"] or datetime.max.replace(tzinfo=ZONA))
        materias.append({
            "nombre": nombre, "color": COLORES[sum(map(ord, nombre)) % len(COLORES)],
            "tareas": [{"id": i["id"], "titulo": i["titulo"],
                        "entrega": i["limite"].strftime("%d/%m") if i["limite"] else "sin fecha"}
                       for i in suyas]})

    return {
        "tareas": tareas, "cursos": materias, "cal": cal, "hoy_iso": hoy.isoformat(),
        "fecha_hoy": f"{DIAS_SEMANA[hoy.weekday()].capitalize()} {hoy.day} de {MESES[hoy.month - 1]}",
        "semana": [{"letra": DIAS_SEMANA[(hoy + timedelta(days=i)).weekday()][0].upper(),
                    "num": (hoy + timedelta(days=i)).day, "hoy": i == 0,
                    "tiene": (hoy + timedelta(days=i)) in dias} for i in range(7)],
        "hoy": next((p for p in por_dia if p["fecha"] == hoy), None),
        "proximos": [{"corto": DIAS_SEMANA[p["fecha"].weekday()][:3].capitalize(),
                      "num": p["fecha"].day, "bloques": p["bloques"]}
                     for p in por_dia if p["fecha"] != hoy],
        "avisos": [f"{estado_de(i)}: {i['titulo']}" for i in items
                   if i["limite"] and estado_de(i) != "OK"],
    }


def sincronizar():
    """Lee Classroom, analiza con IA las tareas nuevas y rearma todo."""
    with candado:
        try:
            load_dotenv()
            clave_api = os.getenv("GEMINI_API_KEY")
            cliente = genai.Client(api_key=clave_api) if clave_api else None
            ahora = datetime.now(ZONA)
            servicio = obtener_servicio()
            cursos = servicio.courses().list(courseStates=["ACTIVE"]).execute().get("courses", [])
            tareas = [t for t in obtener_tareas(servicio)
                      if t["estado"] in ESTADOS_PENDIENTES
                      and (t["limite"] is None or t["limite"] >= ahora)]

            bd = bd_con_manuales()
            filas = bd.execute("SELECT id, curso, titulo, descripcion, fecha FROM manuales WHERE hecha = 0").fetchall()
            for mid, curso, titulo, desc, fecha in filas:
                try:
                    limite = datetime.strptime(fecha, "%Y-%m-%d").replace(hour=23, minute=59, tzinfo=ZONA)
                except ValueError:
                    continue
                if limite >= ahora:
                    tareas.append({"curso": curso, "titulo": titulo, "descripcion": desc or "",
                                   "limite": limite, "estado": "CREATED", "link": "", "manual_id": mid})
            ajustes = {c: (f, ig) for c, f, ig in
                       bd.execute("SELECT clave, fecha, ignorada FROM ajustes")}
            visibles = []
            for t in tareas:
                aj = ajustes.get(clave_de(t))
                if aj and aj[1]:
                    continue  # la marcaste como "ignorar"
                if aj and aj[0] and t["limite"] is None and not t.get("manual_id"):
                    try:
                        t["limite"] = datetime.strptime(aj[0], "%Y-%m-%d").replace(
                            hour=23, minute=59, tzinfo=ZONA)
                    except ValueError:
                        pass
                    if t["limite"] and t["limite"] < ahora:
                        continue
                visibles.append(t)
            tareas = visibles
            estado["ignoradas"] = sorted(c for c, (f, ig) in ajustes.items() if ig)

            for t in tareas:
                clave = clave_de(t)
                limite = t["limite"].isoformat() if t["limite"] else None
                if bd.execute("SELECT 1 FROM analisis WHERE clave = ?", (clave,)).fetchone():
                    bd.execute("UPDATE analisis SET limite = ? WHERE clave = ?", (limite, clave))
                    continue
                if cliente is None:
                    continue
                datos = analizar_con_ia(cliente, t)
                if datos is None:
                    continue
                bd.execute("INSERT INTO analisis VALUES (?, ?, ?, ?, ?, ?, ?, ?)",
                           (clave, t["curso"], t["titulo"], limite, datos.get("horas_estimadas"),
                            datos.get("dificultad"),
                            json.dumps(datos.get("pasos", []), ensure_ascii=False),
                            ahora.isoformat()))
                bd.commit()
            bd.commit()

            items = juntar(bd, tareas)
            bd.close()
            dias = armar_cronograma([i for i in items if i["limite"]], ahora.date())
            estado["datos"] = preparar(items, dias, cursos, ahora.date())
            estado["actualizado"] = ahora.strftime("%d/%m %H:%M")
            estado["error"] = None
            estado["crudo"] = (items, dias)
            try:
                procesar(items, dias, ahora)  # avisos por Telegram
            except Exception as error:
                print("Error al mandar avisos:", error)
        except Exception as error:
            estado["error"] = str(error)[:200]
            print("Error al sincronizar:", error)


